# Initialize a dictionary to keep track of the values visited
visited = {cell: 0 for cell in grid}

# Initialize a priority queue to store the cells to visit
queue = deque([(0, 0)])

# Loop until the priority queue is empty
while queue:
    # Get the next cell and its distance from the starting cell
    distance, cell = queue.popleft()

    # If the cell has not been visited before, mark it as visited and
    # add it to the priority queue
    if cell not in visited:
        visited[cell] = distance
        queue.append((distance + 1, cell))

    # If the cell is the target cell, return the list of values visited
    if cell == grid[0]:
        return visited.values()

    # For each neighbor cell of the current cell
    for neighbor in grid[cell]:
        # If the neighbor has not been visited, mark it as visited and
        # add it to the priority queue
        if neighbor not in visited:
            visited[neighbor] = distance + 1
            queue.append((distance + 1, neighbor))

